17	/// Return a new boolean expression determines whether a batch can be skipped based on min, max and
18	/// null count statistics.
19	///
20	/// This is conversative and may return `None` or `false` when an expression is not yet supported.
21	///
22	/// To evaluate, the expression it is given all the original column appended with `_min` and
23	/// `_max`. The `min` or `max` cannot be null and when they are null it is assumed they are not
24	/// known.
25	pub fn aexpr_to_skip_batch_predicate(
26	    e: Node,
27	    expr_arena: &mut Arena<AExpr>,
28	    schema: &Schema,
29	) -> Option<Node> {
30	    aexpr_to_skip_batch_predicate_rec(e, expr_arena, schema, 0)
31	}
32	
33	fn does_dtype_have_sufficient_order(dtype: &DataType) -> bool {
34	    // Rules surrounding floats are really complicated. I should get around to that.
35	    !dtype.is_nested() && !dtype.is_float() && !dtype.is_null() && !dtype.is_categorical()
36	}
37	
38	fn is_stat_defined(
39	    expr: impl IntoAExprBuilder,
40	    dtype: &DataType,
41	    arena: &mut Arena<AExpr>,
42	) -> AExprBuilder {
43	    let mut expr = expr.into_aexpr_builder();
44	    expr = expr.is_not_null(arena);
45	    if dtype.is_float() {
46	        let is_not_nan = expr.is_not_nan(arena);
47	        expr = expr.and(is_not_nan, arena);
48	    }
49	    expr
50	}
51	
52	#[recursive::recursive]
53	fn aexpr_to_skip_batch_predicate_rec(
54	    e: Node,
55	    arena: &mut Arena<AExpr>,
56	    schema: &Schema,
57	    depth: usize,
58	) -> Option<Node> {
59	    use Operator as O;
60	
61	    macro_rules! rec {
62	        ($node:expr) => {{ aexpr_to_skip_batch_predicate_rec($node, arena, schema, depth + 1) }};
63	    }
64	    macro_rules! lv_cases {
65	        (
66	            $lv:expr, $lv_node:expr,
67	            null: $null_case:expr,
68	            not_null: $non_null_case:expr $(,)?
69	        ) => {{
70	            if let Some(lv) = $lv {
71	                if lv.is_null() {
72	                    $null_case
73	                } else {
74	                    $non_null_case
75	                }
76	            } else {
77	                let lv_node = AExprBuilder::new_from_node($lv_node);
78	
79	                let lv_is_null = lv_node.has_nulls(arena);
80	                let lv_not_null = lv_node.has_no_nulls(arena);
81	
82	                let null_case = lv_is_null.and($null_case, arena);
83	                let non_null_case = lv_not_null.and($non_null_case, arena);
84	
85	                null_case.or(non_null_case, arena).node()
86	            }
87	        }};
88	    }
89	    macro_rules! col {
90	        (len) => {{ col!(PlSmallStr::from_static("len")) }};
91	        ($name:expr) => {{ AExprBuilder::new_from_node(arena.add(AExpr::Column($name))) }};
92	        (min: $name:expr) => {{ col!(format_pl_smallstr!("{}_min", $name)) }};
93	        (max: $name:expr) => {{ col!(format_pl_smallstr!("{}_max", $name)) }};
94	        (null_count: $name:expr) => {{ col!(format_pl_smallstr!("{}_nc", $name)) }};
95	    }
96	    macro_rules! lv {
97	        ($lv:expr) => {{ AExprBuilder::lit_scalar(Scalar::from($lv), arena) }};
98	        (idx: $lv:expr) => {{ AExprBuilder::lit_scalar(Scalar::new_idxsize($lv), arena) }};
99	    }
100	
101	    let specialized = (|| {
102	        if let Some(Some(lv)) = constant_evaluate(e, arena, schema, 0) {
103	            if let Some(av) = lv.to_any_value() {
104	                return match av {
105	                    AnyValue::Null => Some(lv!(true).node()),
106	                    AnyValue::Boolean(b) => Some(lv!(!b).node()),
107	                    _ => None,
108	                };
109	            }
110	        }
111	
112	        match arena.get(e) {
113	            AExpr::Element => None,
114	            AExpr::Explode { .. } => None,
115	            AExpr::Column(_) => None,
116	            #[cfg(feature = "dtype-struct")]
117	            AExpr::StructField(_) => None,
118	            AExpr::Literal(_) => None,
119	            AExpr::BinaryExpr { left, op, right } => {
120	                let left = *left;
121	                let right = *right;
122	
123	                match op {
124	                    O::Eq | O::EqValidity => {
125	                        let ((col, _), (lv, lv_node)) =
126	                            get_binary_expr_col_and_lv(left, right, arena, schema)?;
127	                        let dtype = schema.get(col)?;
128	
129	                        if !does_dtype_have_sufficient_order(dtype) {
130	                            return None;
131	                        }
132	
133	                        let op = *op;
134	                        let col = col.clone();
135	
136	                        // col(A) == B -> {
137	                        //     null_count(A) == 0                              , if B.is_null(),
138	                        //     null_count(A) == LEN || min(A) > B || max(A) < B, if B.is_not_null(),
139	                        // }
140	
141	                        Some(lv_cases!(
142	                            lv, lv_node,
143	                            null: {
144	                                if matches!(op, O::Eq) {
145	                                    lv!(false).node()
146	                                } else {
147	                                    let col_nc = col!(null_count: col);
148	                                    let idx_zero = lv!(idx: 0);
149	                                    col_nc.eq(idx_zero, arena).node()
150	                                }
151	                            },
152	                            not_null: {
153	                                let col_min = col!(min: col);
154	                                let col_max = col!(max: col);
155	
156	                                let min_is_defined = is_stat_defined(col_min.node(), dtype, arena);
157	                                let max_is_defined = is_stat_defined(col_max.node(), dtype, arena);
158	
159	                                let min_gt = col_min.gt(lv_node, arena);
160	                                let min_gt = min_gt.and(min_is_defined, arena);
161	
162	                                let max_lt = col_max.lt(lv_node, arena);
163	                                let max_lt = max_lt.and(max_is_defined, arena);
164	
165	                                let col_nc = col!(null_count: col);
166	                                let len = col!(len);
167	                                let all_nulls = col_nc.eq(len, arena);
168	
169	                                all_nulls.or(min_gt, arena).or(max_lt, arena).node()
170	                            }
171	                        ))
172	                    },
173	                    O::NotEq | O::NotEqValidity => {
174	                        let ((col, _), (lv, lv_node)) =
