24	/// A resolved reference to a (possibly nested) statistics target: a top-level column,
25	/// optionally followed by a struct-field path.
26	///
27	/// The skip-batch statistics frame carries `<col>_min` / `<col>_max` / `<col>_nc` columns
28	/// whose shape mirrors the data column. A struct field `s.a` is therefore read out of the
29	/// struct-typed statistics column as `col("s_min").struct.field("a")` (and likewise for
30	/// `_max` / `_nc`), letting the existing scalar handlers prune on an individual field even
31	/// when sibling fields vary.
32	#[derive(Clone)]
33	struct StatTarget {
34	    col: PlSmallStr,
35	    /// Field path into a struct column, outermost first. Empty for a whole column.
36	    #[cfg_attr(not(feature = "dtype-struct"), allow(dead_code))]
37	    path: Vec<PlSmallStr>,
38	}
39	
40	impl StatTarget {
41	    /// Build the `<col>_<suffix>` statistics accessor, indexing into the struct field path.
42	    fn stat(&self, suffix: &str, arena: &mut Arena<AExpr>) -> AExprBuilder {
43	        #[allow(unused_mut)]
44	        let mut b = AExprBuilder::new_from_node(
45	            arena.add(AExpr::Column(format_pl_smallstr!("{}_{suffix}", self.col))),
46	        );
47	        #[cfg(feature = "dtype-struct")]
48	        {
49	            for field in &self.path {
50	                b = struct_field(b, field.clone(), arena);
51	            }
52	        }
53	        b
54	    }
55	
56	    fn min(&self, arena: &mut Arena<AExpr>) -> AExprBuilder {
57	        self.stat("min", arena)
58	    }
59	    fn max(&self, arena: &mut Arena<AExpr>) -> AExprBuilder {
60	        self.stat("max", arena)
61	    }
62	    fn null_count(&self, arena: &mut Arena<AExpr>) -> AExprBuilder {
63	        self.stat("nc", arena)
64	    }
65	}
66	
67	#[cfg(feature = "dtype-struct")]
68	fn struct_field(base: AExprBuilder, name: PlSmallStr, arena: &mut Arena<AExpr>) -> AExprBuilder {
69	    AExprBuilder::function(
70	        vec![ExprIR::from_node(base.node(), arena)],
71	        IRFunctionExpr::StructExpr(IRStructFunction::FieldByName(name)),
72	        arena,
73	    )
74	}
75	
76	/// Resolve a `col(..)` or chained `col(..).struct.field(..)` expression to a [`StatTarget`].
77	/// Returns `None` for anything else (literals, computed expressions, ...).
78	fn resolve_stat_target(e: Node, arena: &Arena<AExpr>) -> Option<StatTarget> {
79	    match arena.get(e) {
80	        AExpr::Column(c) => Some(StatTarget {
81	            col: c.clone(),
82	            path: Vec::new(),
83	        }),
84	        #[cfg(feature = "dtype-struct")]
85	        AExpr::Function {
86	            input,
87	            function: IRFunctionExpr::StructExpr(IRStructFunction::FieldByName(name)),
88	            ..
89	        } if input.len() == 1 => {
90	            let mut inner = resolve_stat_target(input[0].node(), arena)?;
91	            inner.path.push(name.clone());
92	            Some(inner)
93	        },
94	        _ => None,
95	    }
96	}
