98	/// The leaf dtype a [`StatTarget`] points at, walking the struct-field path through `schema`.
99	fn target_leaf_dtype<'a>(target: &StatTarget, schema: &'a Schema) -> Option<&'a DataType> {
100	    #[allow(unused_mut)]
101	    let mut dtype = schema.get(&target.col)?;
102	    #[cfg(feature = "dtype-struct")]
103	    {
104	        for field in &target.path {
105	            let DataType::Struct(fields) = dtype else {
106	                return None;
107	            };
108	            dtype = fields
109	                .iter()
110	                .find(|f| f.name() == field)
111	                .map(|f| f.dtype())?;
112	        }
113	    }
114	    Some(dtype)
115	}
