117	/// Collect every scalar leaf reachable from `base` under a struct `dtype`. Used to express
118	/// whole-struct null tests as a conjunction over the per-field null counts.
119	#[cfg(feature = "dtype-struct")]
120	fn struct_leaf_targets(base: &StatTarget, dtype: &DataType, out: &mut Vec<StatTarget>) {
121	    match dtype {
122	        DataType::Struct(fields) => {
123	            for f in fields {
124	                let mut child = base.clone();
125	                child.path.push(f.name().clone());
126	                struct_leaf_targets(&child, f.dtype(), out);
127	            }
128	        },
129	        _ => out.push(base.clone()),
130	    }
131	}
