133	/// Like `get_binary_expr_col_and_lv`, but resolving the column side to a [`StatTarget`] so a
134	/// `struct.field(..)` comparison is recognised too.
135	#[allow(clippy::type_complexity)]
136	fn get_binary_expr_target_and_lv<'a>(
137	    left: Node,
138	    right: Node,
139	    arena: &'a Arena<AExpr>,
140	    schema: &Schema,
141	) -> Option<((StatTarget, Node), (Option<Cow<'a, LiteralValue>>, Node))> {
142	    match (
143	        resolve_stat_target(left, arena),
144	        resolve_stat_target(right, arena),
145	        constant_evaluate(left, arena, schema, 0),
146	        constant_evaluate(right, arena, schema, 0),
147	    ) {
148	        (Some(target), _, _, Some(lv)) => Some(((target, left), (lv, right))),
149	        (_, Some(target), Some(lv), _) => Some(((target, right), (lv, left))),
150	        _ => None,
151	    }
152	}
