170	/// Whether min/max statistics are usable for the given dtype, operator, and literal.
171	///
172	/// Rejects nested, null, and categorical types. For floats, Parquet stats exclude NaN
173	/// but data may contain it. Since NaN is largest under TotalOrd, `col < x` is safe
174	/// (NaN never matches) but `col > x` is not (NaN always matches).
175	/// col >= NaN matches NaN == NaN, but stats exclude NaN so max < NaN can't detect them -> unsafe
176	fn can_use_min_max_stats(
177	    dtype: &DataType,
178	    op: Option<&Operator>,
179	    lv: Option<&LiteralValue>,
180	) -> bool {
181	    if dtype.is_nested() || dtype.is_null() || dtype.is_categorical() {
182	        return false;
183	    }
184	
185	    if !dtype.is_float() {
186	        return true;
187	    }
188	
189	    let lv_is_nan = lv.is_some_and(|lv| lv.is_nan());
190	
191	    use Operator as O;
192	    match op {
193	        Some(O::Lt | O::LtEq) => true,
194	        None | Some(O::Eq | O::EqValidity) => !lv_is_nan && lv.is_some(),
195	        Some(O::Gt) => lv_is_nan,
196	        _ => false,
197	    }
198	}
